use std::fs

struct Tree {
    keys: Vec<int>,
    left: Vec<int>,
    right: Vec<int>,
    root: int,
    out: Vec<string>,
}

impl Tree {
    fn has(self, x: int) -> bool {
        let mut n: int = self.root
        let mut found = false
        while n >= 0 {
            let k = self.keys[n]
            if x == k {
                found = true
                break
            } else if x < k {
                n = self.left[n]
            } else {
                n = self.right[n]
            }
        }
        found
    }

    fn add(self, x: int) {
        let id: int = self.keys.len() as int
        self.keys.push(x)
        self.left.push(-1)
        self.right.push(-1)
        if self.root < 0 {
            self.root = id
        } else {
            let mut n: int = self.root
            let mut going = true
            while going {
                if x < self.keys[n] {
                    if self.left[n] < 0 {
                        self.left[n] = id
                        going = false
                    } else {
                        n = self.left[n]
                    }
                } else {
                    if self.right[n] < 0 {
                        self.right[n] = id
                        going = false
                    } else {
                        n = self.right[n]
                    }
                }
            }
        }
    }

    fn del(self, n: int, x: int) -> int {
        if n < 0 {
            return n
        }
        let k = self.keys[n]
        if x < k {
            let l = self.del(self.left[n], x)
            self.left[n] = l
            n
        } else if x > k {
            let r = self.del(self.right[n], x)
            self.right[n] = r
            n
        } else if self.left[n] < 0 {
            self.right[n]
        } else if self.right[n] < 0 {
            self.left[n]
        } else {
            let mut s: int = self.right[n]
            while self.left[s] >= 0 {
                s = self.left[s]
            }
            let sk = self.keys[s]
            self.keys[n] = sk
            let r = self.del(self.right[n], sk)
            self.right[n] = r
            n
        }
    }

    fn walk(self, n: int) {
        if n >= 0 {
            self.walk(self.left[n])
            let k = self.keys[n]
            self.out.push("${k}")
            self.walk(self.right[n])
        }
    }

    fn hgt(self, n: int) -> int {
        if n < 0 {
            return 0
        }
        let a = self.hgt(self.left[n])
        let b = self.hgt(self.right[n])
        if a > b { a + 1 } else { b + 1 }
    }
}

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut t = Tree { keys: [], left: [], right: [], root: -1, out: [] }
    for line in text.lines() {
        let parts: Vec<string> = line.split_whitespace().collect()
        if parts.len() == 0 {
            continue
        }
        let cmd = parts[0]
        let mut x: int = 0
        if parts.len() > 1 {
            x = parts[1].parse::<int>().unwrap_or(0)
        }
        if cmd == "insert" {
            if t.has(x) {
                println("dup")
            } else {
                t.add(x)
                println("ok")
            }
        } else if cmd == "contains" {
            if t.has(x) { println("yes") } else { println("no") }
        } else if cmd == "delete" {
            if t.has(x) {
                let r = t.root
                let nr = t.del(r, x)
                t.root = nr
                println("ok")
            } else {
                println("missing")
            }
        } else if cmd == "inorder" {
            t.out = []
            let r = t.root
            t.walk(r)
            if t.out.len() == 0 { println("<empty>") } else { println(t.out.join(" ")) }
        } else if cmd == "height" {
            let r = t.root
            let h = t.hgt(r)
            println("${h}")
        } else if cmd == "min" {
            if t.root < 0 {
                println("empty")
            } else {
                let mut n: int = t.root
                while t.left[n] >= 0 {
                    n = t.left[n]
                }
                println("${t.keys[n]}")
            }
        } else if cmd == "max" {
            if t.root < 0 {
                println("empty")
            } else {
                let mut n: int = t.root
                while t.right[n] >= 0 {
                    n = t.right[n]
                }
                println("${t.keys[n]}")
            }
        }
    }
}

